# (substituer_pack.py filtre dessus : `tools/substituer_pack.py <game_dir> <port> mm0`).
#
# Rappels de montage :
#  - le deck `multiple_man` demarre en ALTER-EGO (mm001b, Jamie Madrox) ; `Puzzle.ChangeToFace('mm001b', 'mm001a')` le passe en HEROS (Multiple Man) ;
#  - Rhino 01094 est le vilain (14 PV), 01097b son complot principal ; 01101 Hydra Mercenary (3 PV, Garde 1) ;
#  - les 4 Dupe sont mm002 (physique), mm003 (mental), mm004 (energie), mm005 (polyvalente) : 4 cartes distinctes du meme nom ; PV 3 ;
#  - ressources : 01088 Energy = YY, 01089 Genius = BB, 01090 Strength = RR (le cout d'une carte est GENERIQUE) ;
#  - `Puzzle.EmptyHand()` AVANT toute mesure ; `main_exclusive=[..]` fixe la main ; `jouer=[..]` joue la carte ; `payer_avec=[..]` : cartes de la main depensees ;
#  - `Puzzle.AddToVictoryDisplay('mm012')` : la manigance est en zone de victoire SANS avoir ete jouee (les bonus vivent sur l'identite, RECETTES §3bis) ;
#  - `preferer_option='<debut du libelle>'` force une branche d'un « choose ».
HEROS = "Puzzle.ChangeToFace('mm001b', 'mm001a')"


def D(carte):
    return f"Puzzle.PutIntoPlay('{carte}', under_control=True)"


def _c(nom, pourquoi, mise, declencher, attendu, **cle):
    cas = {'nom': nom, 'pourquoi': pourquoi, 'scenario': cle.pop('scenario', 'rhino'), 'heros': cle.pop('heros', 'multiple_man'),
           'mise_en_place': list(mise), 'declencher': list(declencher), 'verifier': cle.pop('verifier', 'etat_attendu'), 'attendu': attendu}
    cas.update(cle)
    return cas


